1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = { yearsWithMHPCO: number };
14	
15	export type Scenario = {
16	  customer: Customer;
17	  steps: QuoteStep[];
18	};
19	
20	export type ScenarioResults = {
21	  results: unknown[];
22	};
23	
24	const PROCESSING_FEE = 5;
25	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
26	const LOYALTY_DISCOUNT = 0.2;
27	const LOYALTY_YEARS = 2;
28	const FOLLOW_UP_DISCOUNT = 0.15;
29	
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const COMPONENT_TYPES = ["rune", "moonstone"];
43	
44	/** Items are priced per type, because the component block applies to alike items. */
45	const groupByType = (items: Item[]): Map<string, Item[]> =>
46	  items.reduce(
47	    (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
48	    new Map<string, Item[]>(),
49	  );
50	
51	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
52	
53	/**
54	 * Item-level risk surcharges, each a rate on the item's own base premium.
55	 * They are separate addends: unlike the policy-level initial assessment, they
56	 * do not compound with each other or with it.
57	 */
58	const CURSE_SURCHARGE = 0.5;
59	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	
62	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; rate: number }[] = [
63	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
64	  {
65	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
66	    rate: HIGH_ENCHANTMENT_SURCHARGE,
67	  },
68	];
69	
70	const itemSurchargeTotal = (item: Item): number =>
71	  ITEM_SURCHARGE_RULES.filter(({ applies }) => applies(item)).reduce(
72	    (sum, { rate }) => sum + itemBasePremium(item) * rate,
73	    0,
74	  );
75	
76	/**
77	 * A building block of exactly 3 alike components is offered at a special base
78	 * premium. "Alike" means the same type, and the block does not repeat: 4 or 7
79	 * runes are charged per item.
80	 */
81	const formsComponentBlock = (type: string, items: Item[]): boolean =>
82	  COMPONENT_TYPES.includes(type) && items.length === BLOCK_SIZE;
83	
84	const alikeItemsBasePremium = (type: string, items: Item[]): number =>
85	  formsComponentBlock(type, items)
86	    ? BLOCK_BASE_PREMIUM
87	    : items.reduce((sum, item) => sum + itemBasePremium(item), 0);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  [...groupByType(items)].reduce(
91	    (sum, [type, alikeItems]) => sum + alikeItemsBasePremium(type, alikeItems),
92	    0,
93	  );
94	
95	/** Premiums are rounded in the MHPCO's favour, i.e. up. */
96	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
97	
98	/**
99	 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
100	 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
101	 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
102	 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
103	 */
104	const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;
105	
106	const policyItemSurchargeTotal = (items: Item[]): number =>
107	  items.reduce((sum, item) => sum + itemSurchargeTotal(item), 0);
108	
109	/**
110	 * Policy-level modifiers, each a signed rate on the policy base premium.
111	 * Like the item-level surcharges they are independent addends: they do not
112	 * compound with one another. A discount is simply a negative rate.
113	 */
114	type PolicyContext = { customer: Customer; contractsIssued: number };
115	
116	const POLICY_MODIFIER_RULES: { applies: (context: PolicyContext) => boolean; rate: number }[] = [
117	  {
118	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
119	    rate: -LOYALTY_DISCOUNT,
120	  },
121	  { applies: ({ contractsIssued }) => contractsIssued > 0, rate: -FOLLOW_UP_DISCOUNT },
122	];
123	
124	const policyModifierTotal = (basePremium: number, context: PolicyContext): number =>
125	  POLICY_MODIFIER_RULES.filter(({ applies }) => applies(context)).reduce(
126	    (sum, { rate }) => sum + basePremium * rate,
127	    0,
128	  );
129	
130	/**
131	 * The premium is the policy base premium plus a set of independent addends,
132	 * each a rate on that same base — they do not compound with one another:
133	 *
134	 *   100 base + 50 curse + 30 high ench - 20 loyalty + 10 first insurance = 170, + 5 fee
135	 *
136	 * The initial assessment surcharge is expressed via `withSurcharge` (base plus
137	 * its own rate) rather than as a bare addend, to keep the IEEE-754 behaviour
138	 * documented there.
139	 */
140	const quote = (step: QuoteStep, context: PolicyContext): { premium: number } => {
141	  const basePremium = policyBasePremium(step.items);
142	  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
143	  const itemSurcharges = policyItemSurchargeTotal(step.items);
144	  const policyModifiers = policyModifierTotal(basePremium, context);
145	
146	  return {
147	    premium: roundInMHPCOsFavour(
148	      assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
149	    ),
150	  };
151	};
152	
153	export const runScenario = (scenario: Scenario): ScenarioResults => {
154	  let contractsIssued = 0;
155	  const results = scenario.steps.map((step) => {
156	    const result = quote(step, { customer: scenario.customer, contractsIssued });
157	    contractsIssued += 1;
158	
159	    return result;
160	  });
161	
162	  return { results };
163	};
