const quote = (step: QuoteStep, state: ScenarioState): { premium: number } => {
  const basePremium = policyBasePremium(step.items);
  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
  const itemSurcharges = policyItemSurchargeTotal(step.items);
  const policyModifiers = policyModifierTotal(basePremium, state);

  return {
    premium: roundInMHPCOsFavour(
      assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
    ),
  };
};

/**
 * Steps are processed in order and later steps depend on earlier ones — a quote
 * issues a contract that discounts every following quote. Each step therefore
 * maps its incoming state to a result plus the state the next step sees.
 */
const runStep = (
  step: QuoteStep,
  state: ScenarioState,
): { result: unknown; nextState: ScenarioState } => ({
  result: quote(step, state),
  nextState: { ...state, contractsIssued: state.contractsIssued + 1 },
});

export const runScenario = (scenario: Scenario): ScenarioResults => {
  const { results } = scenario.steps.reduce<{
    results: unknown[];
    state: ScenarioState;
  }>(
    ({ results, state }, step) => {
      const { result, nextState } = runStep(step, state);

      return { results: [...results, result], state: nextState };
    },
    { results: [], state: { customer: scenario.customer, contractsIssued: 0 } },
  );

  return { results };
};
